use super::KernelRule;

#[allow(clippy::too_many_lines)]
fn slice_vector_admission() -> Vec<KernelRule> {
    vec![
        // ── Rule 1 (category N — dtype + alignment specialization, the
        // vector-width ADMISSION axis): cubecl #1922. A vector width offered
        // to a strided/overlapping tensor read is valid only if EVERY
        // non-axis stride is a multiple of it; the minimum non-zero stride —
        // or any single-stride proxy — does not certify the rest, because
        // overlapping (unfold) views carry outer strides that are not
        // multiples of the innermost. Broadcast strides (zero) satisfy every
        // width. Over-strict = false negative (safe); under-strict = wrong
        // results. ──
        KernelRule {
            rule_id: "vector-width-admission-checks-every-outer-stride".to_string(),
            gpu_concept: "MECHANISM (the vector-width ADMISSION predicate for a strided tensor read is a check over ALL non-axis strides, never a check over one proxy stride; category N — dtype + alignment specialization): a host-side vector-size selector that picks the widest width a strided view can be read at must validate each candidate width against EVERY stride that can shift the read's base offset — the smallest aligned stride does not certify the rest, because overlapping views (unfold/windowed reads over a larger buffer) carry OUTER strides that are not multiples of the innermost. The founding failure is the predicate the PR replaced, verbatim (crates/cubecl-core/src/lib.rs, the removed lines): the selector computed 'Smallest non-zero stride among non-axis dims. Stride 0 is a broadcast and' / 'never contributes to the source offset, so it can be ignored.' and admitted a width on `axis_shape % vector_size == 0 && next_stride % vector_size == 0` where `next_stride = strides.iter().enumerate().filter_map(|(i, &s)| (i != axis && s != 0).then_some(s)).min().unwrap_or(0)` — the MINIMUM non-axis non-zero stride. The repair states the law directly, verbatim (the replacement comment): 'Overlapping views can have outer strides that are not multiples of the' / 'smallest stride. Every non-axis stride must preserve vector alignment;' / 'broadcast strides (zero) satisfy this for every width.' and the fixed predicate (verbatim): `supported_vector_sizes.filter(|&vector_size| { axis_shape % vector_size == 0 && strides.iter().enumerate().all(|(i, stride)| i == axis || stride % vector_size == 0) }).max().ok_or(VectorizationError::NoValidVectorization)` — `.all()` over every stride, the axis itself exempted, stride 0 admitted by the same comparison (0 % w == 0 for every w). THE FAILURE MODE, from the PR's own tests (verbatim, the first): 'parallel_unfold_with_odd_outer_stride_rejects_vectorization' / '// The window stride is aligned, but the second row starts at element 5.' with `try_parallel(&[1, 2, 4], &[2, 2, 2], &[5, 2, 1], 2)` resolving to width 1 — shape [2,2,2] (two unfold rows of two 2-wide windows), strides [5,2,1], axis 2: the minimum non-axis stride is 2 and admits width 2, but the ROW stride is 5, so row 1's windows start at element 5 and a 2-wide vectorized read there is misaligned. The second test pins the width-LIMITING face (verbatim): 'parallel_unfold_outer_stride_limits_vector_width' / '// Width 4 aligns with the windows, but only width 2 aligns with both rows.' — strides [10,4,1], axis 2, width 4 admitted by the window stride (4) alone, refused because 10 % 4 != 0; the correct answer is width 2, not 1. The into_contiguous e2e carries the materialization consequence (verbatim): 'Materializing windows must preserve row starts that are not aligned to the window width.' with row_len 5 / width 2 expecting [0,1,2,3,5,6,7,8] — the row boundary lands mid-vector and the copy must still be elementwise-correct. THE ADMISSION ASYMMETRY is the decision's teeth: the old predicate's own comment conceded the direction of safety, verbatim: 'Unit-size dims are included for simplicity; they only cause false negatives' / '(vectorization disabled) rather than incorrect output.' — an over-strict admission costs throughput (the vectorizer declines), an under-strict admission produces WRONG RESULTS (a misvectorized read lands mid-row); admission predicates must err toward refusal, and a proxy stride (min, first, innermost) is an under-strict check whenever outer strides exist that the proxy did not see. WHY THE MIN-DERIVATION IS THE TRAP: a planner that DERIVES the width from all strides (min trailing-zeros over every stride — the corpus's stride-align-vectorization-key law) is safe by construction because it sees the same set it divides by; the failure class is the planner that VALIDATES a candidate against a SUBSET (the min, the first, the innermost) while other strides exist — subset validation is not admission. THE AXIS EXEMPTION is load-bearing: the axis dim's own stride is excluded because movement WITHIN the axis is what the vectorization batches — the contiguous run along the axis is the read's unit — and axis_shape % vector_size gates the tail; every OTHER dim contributes base-offset shifts that break alignment. DECISION CONTENT: (a) an admission predicate is a universal check — every stride that can move the base offset must be a multiple of the width, never a proxy; (b) broadcast strides (0) are trivially valid and must NOT force the scalar fallback (0 % w == 0 holds for every width; excluding them is also correct — the same predicate shape with a stride != 0 filter — but excluding them via the proxy-min path is how the founding failure read them as the ONLY constraint); (c) over-strict degrades to scalar (safe), under-strict is silent corruption — when the choice is ambiguous, refuse the width; (d) the width is the MAX admitted candidate (`supported_vector_sizes.filter(...).max()`), so a misaligned outer stride LIMITS the width (10,4,1 → 2) rather than killing vectorization outright — gradation, not a cliff; (e) the axis dim is exempt but its SHAPE gates the tail (axis_shape % vector_size). REGIME: host-side vector-size selection for strided/overlapping views (unfold, windowed sliding reads, transposed/permutated views where outer strides are arbitrary); CPU SIMD chunking over a strided matrix (row stride not a multiple of the SIMD width); GPU tensor views whose innermost run is vectorized while outer dims stride freely. ANTI-REGIME: fully contiguous views (one stride chain, the axis shape the only constraint); width DERIVED from all strides (the trailing-zeros key — a different, safe mechanism); vectorizing ALONG an axis whose every outer stride is known-multiple by layout contract (the predicate passes trivially); scalar reads (no width to admit). KINSHIP (do not double-count): stride-align-vectorization-key (entries_popcorn, Batch 7 — the burn-cubecl tune.rs stride_align law) owns the DERIVATION axis (the width is the min trailing-zeros of stride×bytes, capped — it sees ALL strides and is safe-by-construction); THIS owns the ADMISSION axis (a candidate width validated against every outer stride) and the subset-validation failure mode — the two compose (derive from all strides, or admit by checking all strides; never validate by a proxy), cite both for the alignment family. smem-fill-align-chunk-not-element (entries_gpu_37, B137) owns the smem BASE-alignment floor from the fill chunk (a fault class inside the kernel); THIS owns the global-memory view ADMISSION on the host side — different memory space, different decider. ptxas-recoalesces-scalar-runs-wash (entries_gpu_37, B137) owns the escape-arm doctrine (hand-vectorization needs a static alignment PROOF on irregular kernels — 'an odd-element offset still misses the alignment and faults'); THIS is the predicate that PROVES (or refuses) exactly that — compose. contiguity-guard-before-reshape (Batch 7) owns the contiguity ORACLE before a relabel; THIS owns the width admission once a strided view is legitimately read in place. vector-width-pow2-sweep (Batch 7, K) owns the width as an AUTOTUNE dimension — tuning presumes admission; THIS is the validity gate the tuner's candidates must pass. GREP EVIDENCE (over the corpus, 3+ vocabularies): 'vectoriz' → 10 file hits, all other families (the wash rule, the pow2 sweep, the smem fill, the B137 escape arm, lane-map accumulation) — no admission-predicate owner; 'stride' rules → stride-align-vectorization-key (the derivation twin, adjudicated above) + joined-projection-in-place-stride-consumption (the B242 stride-CONSUMPTION layout family) + tp-rank/scale-grid senses — no all-strides admission owner; 'next_stride|min.*stride' → ZERO; 'unfold|window stride' → ZERO (the unfold/window class is new); 'misalign|alignment' → the smem-fill + fault-class families only. NotBenchable here (a host-side vector-size selector's failure is a wrong read, not a slower one — no Pareto axis in this corpus hosts it; the refusal arms, the width-limiting gradation and the broadcast carve-out are CPU-testable and ARE the fixtures). Source: tracel-ai/cubecl PR #1922 (laggui, MERGED 2026-10-26T20:10:36Z, merge 5bd6d17aa883276bf4cf76eadb8ad518c4799647, Apache-2.0) — crates/cubecl-core/src/lib.rs `try_tensor_vector_size_parallel` (the removed min-stride predicate + the replacement all-strides predicate + both comments), the two new `mod tests` entries (parallel_unfold_with_odd_outer_stride_rejects_vectorization, parallel_unfold_outer_stride_limits_vector_width), crates/cubecl-std/src/tests/tensor/into_contiguous.rs (test_into_contiguous_unfold_unaligned_rows) + the test_macros registration. Batch 296 / Plan 301 / Research 337.".to_string(),
            ref_shape: "// ref_shape: the vectorizer validates a candidate width against\n// ONE proxy stride — the minimum non-zero outer stride. On an unfold\n// view the row stride breaks the invariant the proxy cannot see, and\n// row 1's vectorized reads land mid-row (wrong results).\n#![allow(dead_code)]\n\nconst SUPPORTED: [usize; 3] = [4, 2, 1];\n\nfn pick_width_naive(shape: &[usize], strides: &[usize], axis: usize) -> Option<usize> {\n    let axis_shape = *shape.get(axis)?;\n    // the proxy: smallest non-zero stride among the NON-axis dims\n    let next_stride = strides\n        .iter()\n        .enumerate()\n        .filter_map(|(i, &s)| (i != axis && s != 0).then_some(s))\n        .min()\n        .unwrap_or(0);\n    SUPPORTED\n        .iter()\n        .copied()\n        .filter(|&w| axis_shape % w == 0 && next_stride % w == 0)\n        .max()\n}\n\n#[test]\nfn the_proxy_admits_a_width_the_row_stride_breaks() {\n    // unfold windows: shape [2, 2, 4] over rows of length 10 —\n    // strides [10, 4, 1]; the min non-axis stride is 4, so width 4\n    // passes the proxy. Row 1 starts at element 10: 10 % 4 != 0 —\n    // a 4-wide read there is misaligned.\n    let w = pick_width_naive(&[2, 2, 4], &[10, 4, 1], 2).unwrap();\n    assert_eq!(w, 4); // WRONG: admits a misvectorized row-1 read\n}\n".to_string(),
            opt_pattern: "// opt_pattern: admission is a UNIVERSAL check -- every non-axis\n// stride must be a multiple of the width (stride 0 admits every\n// width), the axis exempted, the axis SHAPE gating the tail. A\n// misaligned outer stride LIMITS the width; it never silently passes,\n// and it never forces the scalar width while a wider one aligns.\n#![allow(dead_code)]\n\nconst SUPPORTED: [usize; 3] = [4, 2, 1];\n\nfn pick_width(shape: &[usize], strides: &[usize], axis: usize) -> Option<usize> {\n    let axis_shape = *shape.get(axis)?;\n    if strides.len() != shape.len() || axis >= shape.len() {\n        return None;\n    }\n    SUPPORTED\n        .iter()\n        .copied()\n        .filter(|&w| {\n            axis_shape % w == 0\n                && strides\n                    .iter()\n                    .enumerate()\n                    .all(|(i, &s)| i == axis || s % w == 0)\n        })\n        .max()\n}\n\n#[test]\nfn every_outer_stride_gates_the_width() {\n    // the founding failure: [5, 2, 1] -- the window stride 2 admits\n    // width 2, the row stride 5 refuses it; only the scalar width\n    // stands (a misvectorized row-1 read is corruption, not a slowdown).\n    assert_eq!(pick_width(&[2, 2, 2], &[5, 2, 1], 2), Some(1));\n    // the gradation, not a cliff: [10, 4, 1] -- width 4 aligns with the\n    // windows, but only width 2 aligns with both rows.\n    assert_eq!(pick_width(&[2, 2, 4], &[10, 4, 1], 2), Some(2));\n    // the axis SHAPE gates the tail: an axis of 3 declines 4 and 2 even\n    // when every outer stride aligns.\n    assert_eq!(pick_width(&[2, 2, 3], &[6, 6, 1], 2), Some(1));\n    // malformed strides (one stride per dim is the contract) refuse the\n    // admission outright.\n    assert_eq!(pick_width(&[2, 2, 4], &[4, 1], 2), None);\n}\n\n#[test]\nfn broadcast_stride_zero_admits_every_width() {\n    // stride 0 is a broadcast: it never shifts the base offset, so it\n    // satisfies every width and must not force the scalar fallback.\n    assert_eq!(pick_width(&[4, 2, 4], &[0, 4, 1], 2), Some(4));\n    assert_eq!(pick_width(&[2, 4], &[0, 1], 1), Some(4));\n    // contiguous view: the single non-axis stride aligns -- full width.\n    assert_eq!(pick_width(&[3, 4], &[4, 1], 1), Some(4));\n}\n".to_string(),
        },
    ]
}

pub fn entries() -> Vec<KernelRule> {
    slice_vector_admission()
}
